import{_ as a}from"./chunks/Fixpipe_Int8_Channel_Merge.CobzoAsV.js";import{_ as t,o as r,a as n,b as _}from"./app.Zc0CUjTy.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"Int8 Channel Merge","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/Int8-Channel-Merge"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/Int8-Channel-Merge.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/Int8-Channel-Merge.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1789544578000}'),i={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/Int8-Channel-Merge.md"};function s(l,e,c,o,p,d){return r(),n("div",null,[...e[0]||(e[0]=[_('<div><article class="markdown-body"><h1>Int8 Channel Merge</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中对于目标数据类型被转换为int8_t、uint8_t的情况，Nz输出时该特性自动启用。硬件会将分形矩阵从16×16扩展为16×32。具体规则如下：若输出通道数N是16的偶数倍，则在N方向上，每两个相邻的16×16分形矩阵将合并为一个单一的16×32分形矩阵。若N是16的奇数倍，则通道1至通道（N–16）将被合并，而最后16个通道保持不变，不进行合并。</p><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><p>硬件自动开启，不能配置。</p><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>例如，当目标数据类型为s8，M为32，N为48时，硬件会先将N方向上前两个16×16的分形矩阵合并成一个16×32的矩阵，然后将剩余的16×16分形矩阵直接搬运至L1 Buffer。</p><p><strong>图1</strong> Int8 Channel Merge示意图</p><p><img src="'+a+'" alt></p></article></div>',1)])])}const m=t(i,[["render",s]]);export{h as __pageData,m as default};
